  for (let c = 0; c < s.length; c++) {
    const cp = s.codePointAt(c);
    const len = cp < 0x80 ? 1 : cp < 0x800 ? 2 : cp < 0x10000 ? 3 : 4;
    for (let k = 0; k < len; k++) map[b + k] = c;
    b += len;
    if (cp >= 0x10000) c++;            // surrogate pair: two UTF-16 units
  }
