    if (!m || !m[1].split(/\s+/).includes(sel.class)) return false;
  }
  return true;
}

// Inner HTML of the first element matching {tag, id, class}; null if absent.
// Nested elements with the same tag name are balanced.
function extractElement(html, sel) {
  const tag = (sel.tag || '[a-z][a-z0-9]*').toLowerCase();
  const openRe = new RegExp(`<(${tag})(\\s[^>]*)?>`, 'gi');
  let m;
  while ((m = openRe.exec(html))) {
    if (!attrMatches(m[0], sel)) continue;
    const name = m[1].toLowerCase();
    const re = new RegExp(`<(/?)${name}(?=[\\s>/])[^>]*>`, 'gi');
    re.lastIndex = m.index + m[0].length;
    let depth = 1, t;
    while ((t = re.exec(html))) {
      if (t[0].endsWith('/>')) continue;
      depth += t[1] ? -1 : 1;
      if (depth === 0) return html.slice(m.index + m[0].length, t.index);
    }
    return html.slice(m.index + m[0].length);
  }
  return null;
}

function removeElements(html, names) {
  let out = html;
  for (const n of names) {
    out = out.replace(new RegExp(`<${n}(?=[\\s>/])[\\s\\S]*?</${n}\\s*>`, 'gi'), ' ');
    out = out.replace(new RegExp(`<${n}(?=[\\s>/])[^>]*/>`, 'gi'), ' ');
  }
  return out;
}

// opts: {select: {tag,id,class} | [..] (first match wins), keepBoilerplate: bool}
function htmlToText(html, opts = {}) {
  let h = String(html || '').replace(/<!--[\s\S]*?-->/g, ' ');
  h = removeElements(h, DROP_ELEMENTS);
  let selected = false;
  for (const sel of [].concat(opts.select || [])) {
    const inner = extractElement(h, sel);
    if (inner !== null) { h = inner; selected = true; break; }
  }
  if (!opts.keepBoilerplate) h = removeElements(h, BOILERPLATE_ELEMENTS);
  h = h.replace(/<(\/?)([a-z][a-z0-9]*)(\s[^>]*)?\/?>/gi, (m, close, name) => {
    const n = name.toLowerCase();
    if (/^h[1-6]$/.test(n)) return close ? '\n\n' : `\n\n${'#'.repeat(Number(n[1]))} `;
    if (n === 'br') return '\n';
    if (n === 'li') return close ? '' : '\n- ';
    if (n === 'td' || n === 'th') return ' ';
    if (BLOCK_TAGS.has(n)) return '\n\n';
    return '';
  });
  h = h.replace(/<[^>]*>/g, '');           // anything left (malformed tags)
  let text = normalizeText(decodeEntities(h));
  // a heading marker left alone on its line (empty heading) is dropped
  text = text.replace(/^#{1,6}\s*$/gm, '').replace(/\n{3,}/g, '\n\n').trim();
  return { text, selected };
}

// ---------------------------------------------------------------------------
// PDF pages (one string per page, lines separated by "\n", as n8n's Extract
// From File node returns them with joinPages=false) -> paragraphs.
const TERMINAL_RE = /[.!?:;؟»)\]"”]$/;
const STRUCTURE_LINE_RE = /^(#{1,6}\s|[-•*–]\s|\(?\d{1,3}[.)-]\s|\(?[a-z][.)]\s|(article|art\.?)\s*(premier|1er|\d)|(livre|titre|chapitre|section|sous-section|paragraphe)\s|(الفصل|الباب|العنوان|القسم|الفرع|الكتاب)\s|[IVXLC]+[.-]\s)/i;

function pdfPagesToText(pages, opts = {}) {
  const pageLines = pages.map((p) => normalizeText(p).split('\n').map((l) => l.trim()).filter((l) => l.length));
  // Running headers/footers: first/last two lines repeated on more than half of
  // the pages (digits ignored, so "Page 3" and "Page 4" count as the same line).
  const key = (l) => l.replace(/\d+/g, '#');
  const counts = new Map();
  for (const lines of pageLines) {
    const edge = new Set([...lines.slice(0, 2), ...lines.slice(-2)].map(key));
    for (const k of edge) counts.set(k, (counts.get(k) || 0) + 1);
  }
  const minRepeats = Math.max(3, Math.ceil(pages.length / 2));
  // structural lines ("Article 12", "Chapitre 3") repeat in shape on many pages but are content
  const isRunning = (l, i, n) => (i < 2 || i >= n - 2) && !STRUCTURE_LINE_RE.test(l)
    && (counts.get(key(l)) || 0) >= minRepeats;
  const isPageNumber = (l) => /^(page\s*)?[-–]?\s*\d{1,4}\s*[-–]?(\s*\/\s*\d{1,4})?$/i.test(l);

  const kept = [];
  const pageStarts = [];
  for (const lines of pageLines) {
    pageStarts.push(kept.length);
    lines.forEach((l, i) => { if (!isRunning(l, i, lines.length) && !isPageNumber(l)) kept.push(l); });
  }
  const lengths = kept.map((l) => l.length).sort((a, b) => a - b);
  const median = lengths.length ? lengths[Math.floor(lengths.length / 2)] : 0;
  const shortLine = Math.max(20, Math.floor(median * 0.6));

  const paras = [];
  let cur = '';
  kept.forEach((line, i) => {
    if (!cur) { cur = line; return; }
    const prev = kept[i - 1];
    // new paragraph when the line starts a structural unit, or the previous line
    // ends a sentence or is short (a wrapped line runs to the right margin)
    const breakHere = STRUCTURE_LINE_RE.test(line) || TERMINAL_RE.test(prev) || prev.length < shortLine;
    if (breakHere && !/-$/.test(prev)) { paras.push(cur); cur = line; return; }
    if (/[a-zà-ÿ]-$/i.test(cur) && /^[a-zà-ÿ]/.test(line)) cur = cur.slice(0, -1) + line;   // hyphenated word
    else cur += ' ' + line;
  });
  if (cur) paras.push(cur);
  return { text: normalizeText(paras.join('\n\n')), pages: pages.length, lines_dropped: pageLines.flat().length - kept.length };
}

// ---------------------------------------------------------------------------
// Sentence boundaries (French, English, Arabic). Returns character offsets
// where a new sentence starts, inside [start, end).
const ABBREV = new Set(['art', 'arts', 'al', 'cf', 'ex', 'etc', 'n', 'no', 'nos', 'p', 'pp', 'm', 'mm', 'mme', 'dr',
  'mr', 'mrs', 'st', 'vol', 'ch', 'chap', 'sect', 'op', 'loc', 'ibid', 'i.e', 'e.g', 'vs', 'av', 'bd', 'tél', 'tel']);

function sentenceStarts(text, start = 0, end = text.length) {
  const out = [];
  const re = /([.!?؟…]+)(["”»)\]]*)(\s+)(?=\S)/g;
  re.lastIndex = start;
  let m;
  while ((m = re.exec(text)) && m.index < end) {
    const next = m.index + m[0].length;
    if (next >= end) break;
    const before = text.slice(Math.max(start, m.index - 12), m.index);
    const word = (/([A-Za-zÀ-ÿ.]+)$/.exec(before) || [])[1] || '';
    if (m[1] === '.' && ABBREV.has(word.toLowerCase())) continue;
    if (m[1] === '.' && /\d$/.test(before) && /^\d/.test(text[next])) continue;   // 1. 2  / 3.5
    if (m[1] === '.' && /^[a-zà-ÿ]/.test(text[next])) continue;                   // lower case follows
    out.push(next);
  }
  // line breaks between paragraphs are always boundaries
  const nl = /\n+/g;
  nl.lastIndex = start;
  while ((m = nl.exec(text)) && m.index < end) {
    const next = m.index + m[0].length;
    if (next < end) out.push(next);
  }
  return [...new Set(out)].sort((a, b) => a - b);
}

if (typeof module !== 'undefined') {
  module.exports = { normalizeText, sniffCharset, decodeBytes, decodeEntities, extractElement, htmlToText,
    pdfPagesToText, sentenceStarts };
}

// Token offsets for chunking, from the TEI /tokenize endpoint (XLM-RoBERTa
// tokenizer of multilingual-e5-large, the same vocabulary as bge-m3; D-035).
//
// The document is cut into pieces of at most maxChars characters at whitespace,
// each piece is tokenized without special tokens, and the token offsets are
// shifted back to document positions. Cutting at whitespace does not change the
// tokens of a SentencePiece tokenizer, whose pieces never span whitespace.

function splitPieces(text, maxChars = 1000) {
  const pieces = [];
  let i = 0;
  const n = text.length;
  while (i < n) {
    let end = Math.min(n, i + maxChars);
    if (end < n) {
      const ws = text.lastIndexOf(' ', end);
      const nl = text.lastIndexOf('\n', end);
      const cut = Math.max(ws, nl);
      if (cut > i) end = cut;          // a piece with no whitespace at all is cut hard
    }
    pieces.push({ start: i, text: text.slice(i, end) });
    i = end;
  }
  return pieces;
}

// Byte offset (UTF-8) -> UTF-16 index table for one string.
function byteToCharMap(s) {
  const map = new Int32Array(Buffer.byteLength(s, 'utf8') + 1);
  let b = 0;
  for (let c = 0; c < s.length; c++) {
    const cp = s.codePointAt(c);
    const len = cp < 0x80 ? 1 : cp < 0x800 ? 2 : cp < 0x10000 ? 3 : 4;
    for (let k = 0; k < len; k++) map[b + k] = c;
    b += len;
    if (cp >= 0x10000) c++;            // surrogate pair: two UTF-16 units
  }
  map[b] = s.length;
  return map;
}

// TEI returns offsets either in characters or in UTF-8 bytes depending on the
// version; tell them apart on the piece itself (D-035). Pure ASCII pieces are
// the same either way.
function offsetUnit(pieceText, tokens) {
  const bytes = Buffer.byteLength(pieceText, 'utf8');
  if (bytes === pieceText.length) return 'char';
  const maxStop = tokens.reduce((m, t) => Math.max(m, t.stop ?? t.end ?? 0), 0);
  return maxStop > pieceText.length ? 'byte' : 'char';
}

// pieceTokens: TEI answer for one piece, [{id, text, special, start, stop}].
// Returns [[startChar, endChar], ...] in document positions, specials dropped.
function pieceOffsets(piece, pieceTokens) {
  const toks = (pieceTokens || []).filter((t) => !t.special && (t.start ?? null) !== null);
  const unit = offsetUnit(piece.text, toks);
  const map = unit === 'byte' ? byteToCharMap(piece.text) : null;
  const out = [];
  for (const t of toks) {
    let s = t.start, e = t.stop ?? t.end;
    if (map) { s = map[s]; e = map[e]; }
    // SentencePiece puts the word-start marker on the token, and some tokenizers
    // include the preceding space in the offsets: trim it so spans start on text.
    while (s < e && /\s/.test(piece.text[s])) s++;
    if (e > s) out.push([piece.start + s, piece.start + e]);
  }
  return { offsets: out, unit };
}

function assembleTokens(pieces, answers) {
  const all = [];
  const units = new Set();
  pieces.forEach((p, i) => {
    const r = pieceOffsets(p, answers[i]);
    units.add(r.unit);
    for (const o of r.offsets) all.push(o);
  });
  return { tokens: all, units: [...units] };
}

// Number of tokens fully inside [start, end): binary search on sorted tokens.
function lowerBound(tokens, pos, idx) {
  let lo = 0, hi = tokens.length;
  while (lo < hi) { const mid = (lo + hi) >> 1; if (tokens[mid][idx] < pos) lo = mid + 1; else hi = mid; }
  return lo;
}
function countTokens(tokens, start, end) {
  const a = lowerBound(tokens, start, 0);
  const b = lowerBound(tokens, end + 1, 1);   // tokens with end <= end
  return Math.max(0, b - a);
}

if (typeof module !== 'undefined') {
  module.exports = { splitPieces, byteToCharMap, offsetUnit, pieceOffsets, assembleTokens, countTokens, lowerBound };
}

// Document structure for strategy B (spec 10.3): headings and articles of
// French and Arabic legal texts, markdown-style headings from cleaned HTML,
// and plain paragraphs. Works on the cleaned text from kb/lib/text.js.
//
// parseStructure(text) -> {
//   headings: [{start, end, level, label}],           // heading lines
//   units:    [{start, end, kind: 'article'|'para', ref, path: [heading index...]}]
// }
// Units never contain heading lines. Offsets are 0-based, end exclusive.

const FR_HEADING = [
  [/^livre\b/i, 1], [/^(titre|title)\b/i, 2], [/^(chapitre|chapter)\b/i, 3],
  [/^(section)\b/i, 4], [/^(sous-section|sous section)\b/i, 5], [/^(paragraphe|§)\s*\S/i, 6],
];
const AR_HEADING = [
  [/^الكتاب\s/, 1], [/^(العنوان|الباب)\s/, 2], [/^(القسم)\s/, 4], [/^(الفرع|الجزء)\s/, 5],
];
// "Article 727", "Art. 727 bis", "ARTICLE PREMIER", "Article 2 (nouveau)", "الفصل 727", "الفصل الأول"
const ARTICLE_FR = /^(?:article|art\.)\s*(premier|1er|\d+(?:\s*(?:bis|ter|quater|quinquies|sexies|septies|octies|nonies|decies))?(?:\s*\((?:nouveau|modifié|abrogé)\))?)\s*(?:[.:\-–—)]|$|\s)/i;
const ARTICLE_AR = /^(?:الفصل|فصل)\s*((?:\d+|[٠-٩]+)(?:\s*(?:مكرر|ثالثا|رابعا))?|الأول|الاول|أول|اول)\s*(?:[.:\-–—)]|$|\s)/;

function headingLevel(line) {
  const md = /^(#{1,6})\s+\S/.exec(line);
  if (md) return { level: md[1].length, md: true };
  if (line.length > 120 || /[.,;]$/.test(line)) return null;   // a body sentence, not a heading
  for (const [re, lvl] of FR_HEADING) if (re.test(line)) return { level: lvl, md: false };
  for (const [re, lvl] of AR_HEADING) if (re.test(line)) return { level: lvl, md: false };
  return null;
}

function articleRef(line) {
  let m = ARTICLE_FR.exec(line);
  if (m) {
    const n = m[1].replace(/\s+/g, ' ').replace(/^1er$/i, '1').replace(/^premier$/i, '1');
    return n.replace(/\s*\((nouveau|modifié|abrogé)\)/i, '');
  }
  m = ARTICLE_AR.exec(line);
  if (m) {
    let n = m[1].replace(/[٠-٩]/g, (d) => String(d.charCodeAt(0) - 0x0660));
    if (/^(الأول|الاول|أول|اول)$/.test(n)) n = '1';
    return n.replace(/\s+/g, ' ');
  }
  return null;
}

// A legal heading is often followed by its title on the next line, e.g.
// "TITRE PREMIER" / "DU LOUAGE". Such a short line without final punctuation
// is folded into the heading.
function isTitleContinuation(line) {
  if (!line || line.length > 120 || /[.;:]$/.test(line)) return false;
  if (articleRef(line) || headingLevel(line)) return false;
  const letters = line.replace(/[^A-Za-zÀ-ÿ]/g, '');
  const upper = letters && letters === letters.toUpperCase();
  return upper || /^[؀-ۿ]/.test(line) && line.length < 80;
}

function parseStructure(text) {
  const lines = [];
  let pos = 0;
  for (const l of text.split('\n')) { lines.push({ start: pos, end: pos + l.length, text: l }); pos += l.length + 1; }

  const headings = [];
  const units = [];
  const stack = [];                      // [{level, idx}]
  let cur = null;                        // open unit
  const path = () => stack.map((s) => s.idx);
  const close = () => { if (cur) { units.push(cur); cur = null; } };

  for (let i = 0; i < lines.length; i++) {
    const ln = lines[i];
    const t = ln.text;
    if (!t.trim()) {                      // blank line ends a paragraph unit, not an article
      if (cur && cur.kind === 'para') close();
      continue;
    }
    const h = headingLevel(t);
    const ref = h ? null : articleRef(t);
    if (h) {
      close();
      let end = ln.end;
      let label = t.replace(/^#{1,6}\s+/, '');
      // fold a title line that follows a legal heading (skipping one blank line)
      if (!h.md) {
        let j = i + 1;
        if (j < lines.length && !lines[j].text.trim()) j++;
        if (j < lines.length && isTitleContinuation(lines[j].text)) {
          label += ' - ' + lines[j].text; end = lines[j].end; i = j;
        }
      }
      while (stack.length && stack[stack.length - 1].level >= h.level) stack.pop();
      headings.push({ start: ln.start, end, level: h.level, label: label.trim() });
      stack.push({ level: h.level, idx: headings.length - 1 });
      continue;
    }
    if (ref) {
      close();
      cur = { start: ln.start, end: ln.end, kind: 'article', ref, path: path() };
      continue;
    }
    if (cur) { cur.end = ln.end; continue; }
    cur = { start: ln.start, end: ln.end, kind: 'para', ref: null, path: path() };
  }
  close();
  return { headings, units };
}

if (typeof module !== 'undefined') {
  module.exports = { parseStructure, articleRef, headingLevel, isTitleContinuation };
}

// Strategy A, "fixed_500_50" (spec 10.3): windows of 500 tokens with 50
// tokens of overlap over the whole document, ignoring structure. Token
// offsets come from kb/lib/tokens.js. A window's span runs from the start of
// its first token to the end of its last token.
//
// chunkFixed(text, tokens, {size, overlap}) -> [{chunk_index, start_char, end_char, token_count,
//                                              heading_path: [], article_ref: null, metadata}]

function chunkFixed(text, tokens, opts = {}) {
  const size = opts.size || 500;
  const overlap = opts.overlap ?? 50;
  if (overlap >= size) throw new Error('overlap must be smaller than size');
  const stride = size - overlap;
  const out = [];
  if (!tokens.length) return out;
  for (let i = 0; i < tokens.length; i += stride) {
    const j = Math.min(tokens.length, i + size);
    out.push({
      chunk_index: out.length,
      start_char: tokens[i][0],
      end_char: tokens[j - 1][1],
      token_count: j - i,
      heading_path: [],
      article_ref: null,
      metadata: { strategy_params: { size, overlap }, first_token: i, last_token: j - 1 },
    });
    if (j === tokens.length) break;
  }
  return out;
}

if (typeof module !== 'undefined') module.exports = { chunkFixed };

// Strategy B, "structure_aware_v1" (spec 10.3).
//  - Units are the document's own: articles, or paragraphs under headings
//    (kb/chunkers/structure.js).
//  - A unit above maxTokens (400) is split at sentence boundaries; a sentence
//    longer than that is cut into token windows.
//  - A chunk under minTokens (150) is merged with a neighbour under the same
//    headings if the result stays within maxTokens. No overlap, so two
//    articles never share text.
//  - The embedded text is "heading > heading\n" + chunk text, stored in
//    metadata.embed_text so the embedding input can be reproduced.
// Needs kb/lib/tokens.js (countTokens, lowerBound) and kb/lib/text.js
// (sentenceStarts) in the same scope.

function chunkStructureAware(text, tokens, structure, opts = {}) {
  const maxT = opts.maxTokens || 400;
  const minT = opts.minTokens || 150;
  const embedMax = opts.embedMaxTokens || 510;
  const cite = opts.citeAs ? opts.citeAs + ' ' : '';
  const { headings, units } = structure;
  const count = (s, e) => countTokens(tokens, s, e);

  // 1. split long units
  const pieces = [];
  for (const u of units) {
    const n = count(u.start, u.end);
    if (n === 0) continue;
    if (n <= maxT) { pieces.push({ ...u, tokens: n, part: null }); continue; }
    const starts = [u.start, ...sentenceStarts(text, u.start, u.end).filter((p) => p > u.start), u.end];
    const segs = [];
    let s0 = starts[0];
    for (let k = 1; k < starts.length; k++) {
      const candidateEnd = starts[k];
      // cut before sentence k-1 unless that sentence alone is too long (it is then
      // windowed together with the text before it, see below)
      if (count(s0, candidateEnd) > maxT && starts[k - 1] > s0 && count(starts[k - 1], candidateEnd) <= maxT) {
        segs.push([s0, starts[k - 1]]);
        s0 = starts[k - 1];
      }
    }
    segs.push([s0, u.end]);
    const fine = [];
    for (const [a, b] of segs) {
      if (count(a, b) <= maxT) { fine.push([a, b]); continue; }
      // one sentence above the limit: windows of maxT tokens
      const i0 = lowerBound(tokens, a, 0);
      const i1 = lowerBound(tokens, b + 1, 1);
      for (let i = i0; i < i1; i += maxT) {
        const j = Math.min(i1, i + maxT);
        fine.push([i === i0 ? a : tokens[i][0], j === i1 ? b : tokens[j - 1][1]]);
      }
    }
    fine.forEach(([a, b], k) => {
      const ta = trimSpan(text, a, b);
      if (ta) pieces.push({ ...u, start: ta[0], end: ta[1], tokens: count(ta[0], ta[1]), part: `${k + 1}/${fine.length}` });
    });
  }

  // 2. merge small pieces with a neighbour under the same headings
  const samePath = (a, b) => a.path.length === b.path.length && a.path.every((x, i) => x === b.path[i]);
  const merged = [];
  for (const p of pieces) {
    const last = merged[merged.length - 1];
    if (last && samePath(last, p) && (last.tokens < minT || p.tokens < minT)) {
      const n = count(last.start, p.end);
      if (n <= maxT) { last.end = p.end; last.tokens = n; last.members.push(p); continue; }
    }
    merged.push({ start: p.start, end: p.end, path: p.path, tokens: p.tokens, members: [p] });
  }

  // 3. labels, article refs, embedding text
  return merged.map((c, idx) => {
    const refs = [...new Set(c.members.filter((m) => m.ref).map((m) => m.ref))];
    const article_ref = refs.length === 0 ? null
      : refs.length === 1 ? `${cite}art. ${refs[0]}` : `${cite}art. ${refs[0]}-${refs[refs.length - 1]}`;
    let path = c.path.slice();
    const label = (i) => headings[i].label.slice(0, 150);
    const headTokens = (p) => p.reduce((s, i) => s + count(headings[i].start, headings[i].end) + 2, 0);
    let dropped = 0;
    while (path.length && c.tokens + headTokens(path) > embedMax) { path = path.slice(1); dropped++; }
    const content = text.slice(c.start, c.end);
    const heading_path = c.path.map(label);
    const embed_text = path.length ? path.map(label).join(' > ') + '\n' + content : content;
    return {
      chunk_index: idx,
      start_char: c.start,
      end_char: c.end,
      token_count: c.tokens,
      heading_path,
      article_ref,
      metadata: {
        kinds: [...new Set(c.members.map((m) => m.kind))],
        parts: c.members.filter((m) => m.part).map((m) => (m.ref ? m.ref + ' ' : '') + m.part),
        merged_units: c.members.length,
        embed_text,
        embed_token_estimate: c.tokens + headTokens(path),
        headings_dropped_for_length: dropped,
        strategy_params: { max_tokens: maxT, min_tokens: minT },
      },
    };
  });
}

function trimSpan(text, a, b) {
  while (a < b && /\s/.test(text[a])) a++;
  while (b > a && /\s/.test(text[b - 1])) b--;
  return b > a ? [a, b] : null;
}

if (typeof module !== 'undefined') module.exports = { chunkStructureAware, trimSpan };

const x = $('Cleaned').first().json;
const doc = $('Store document').first().json.doc;
