  const parsed = typeof raw === 'string' ? JSON.parse(raw) : raw;
  if (!Array.isArray(parsed)) throw new Error('unexpected /tokenize answer: ' + String(raw).slice(0, 200));
  for (const a of parsed) answers.push(a);
}
if (answers.length !== pieces.length) throw new Error(`tokenize returned ${answers.length} results for ${pieces.length} pieces`);
const { tokens, units } = assembleTokens(pieces, answers);
if (!tokens.length) throw new Error('no tokens');

const strategies = x.cfg.strategies || ['fixed_500_50', 'structure_aware_v1'];
const chunks = [];
const stats = {};
const add = (strategy, list) => {
  const n = list.map((c) => c.token_count);
  const mean = n.reduce((a, b) => a + b, 0) / (n.length || 1);
  const sd = Math.sqrt(n.reduce((a, b) => a + (b - mean) ** 2, 0) / (n.length || 1));
  stats[strategy] = { chunks: list.length, tokens_mean: Math.round(mean * 10) / 10, tokens_sd: Math.round(sd * 10) / 10,
                      tokens_min: Math.min(...n), tokens_max: Math.max(...n) };
  for (const c of list) chunks.push({ strategy, ...c });
};
if (strategies.includes('fixed_500_50')) add('fixed_500_50', chunkFixed(text, tokens, { size: 500, overlap: 50 }));
if (strategies.includes('structure_aware_v1')) {
  const st = parseStructure(text);
  add('structure_aware_v1', chunkStructureAware(text, tokens, st, { maxTokens: 400, minTokens: 150, citeAs: x.source.cite_as }));
  stats.structure_aware_v1.headings = st.headings.length;
  stats.structure_aware_v1.articles = st.units.filter((u) => u.kind === 'article').length;
}
return [{ json: { doc, chunks, stats, document_tokens: tokens.length, offset_units: units, chunk_ms: Date.now() - t0 } }];

// wf.kb.ingest_source > "Embed batches"
// Input: [{chunk_id, strategy, chunk_index}] from "Store chunks". Builds one
// request per batch and model. Embedded text: the chunk text for strategy A,
// metadata.embed_text (heading path + text) for strategy B. Model prefixes come
// from ai.models (multilingual-e5-large: "passage: ").
const x = $('Cleaned').first().json;
const ch = $('Chunk').first().json;
const stored = $input.first().json.ids || [];
const byKey = new Map(ch.chunks.map((c) => [`${c.strategy}|${c.chunk_index}`, c]));
const rows = stored.map((s) => {
  const c = byKey.get(`${s.strategy}|${s.chunk_index}`);
  if (!c) throw new Error(`stored chunk ${s.strategy}/${s.chunk_index} not in the chunker output`);
  const text = (c.metadata && c.metadata.embed_text) || x.content.slice(c.start_char, c.end_char);
  return { chunk_id: s.chunk_id, text };
});
const out = [];
for (const m of x.models) {
  const size = Number(m.endpoint === 'tei' ? x.cfg.batch_e5 || 16 : x.cfg.batch_bge || 32);
  for (let i = 0; i < rows.length; i += size) {
    const b = rows.slice(i, i + size);
    const inputs = b.map((r) => (m.passage_prefix || '') + r.text);
    const req = m.endpoint === 'tei'
      ? { url: `${x.cfg.tei_base_url}/embed`, body: { inputs, normalize: true, truncate: true } }
      : { url: `${x.cfg.ollama_base_url}/api/embed`, body: { model: m.name, input: inputs, truncate: true } };
    out.push({ json: { model: m.name, endpoint: m.endpoint, dims: m.dims, chunk_ids: b.map((r) => r.chunk_id), ...req } });
  }
}
return out;

// wf.kb.ingest_source > "Vectors"
// Input: embedding answers (text) in request order. Pairs vectors with chunk
// ids, checks count and dimension, and groups rows for the database (<= 200
// rows per statement).
const reqs = $('Embed batches').all().map((i) => i.json);
const answers = $input.all().map((i) => i.json.data);
if (answers.length !== reqs.length) throw new Error(`${answers.length} embedding answers for ${reqs.length} requests`);
const groups = new Map();
const timing = {};
reqs.forEach((req, i) => {
  const a = typeof answers[i] === 'string' ? JSON.parse(answers[i]) : answers[i];
  const vecs = req.endpoint === 'tei' ? a : a && a.embeddings;
  if (!Array.isArray(vecs) || vecs.length !== req.chunk_ids.length) {
    throw new Error(`${req.model}: expected ${req.chunk_ids.length} vectors, got ${Array.isArray(vecs) ? vecs.length : typeof vecs}`);
  }
  vecs.forEach((v, j) => {
    if (!Array.isArray(v) || v.length !== req.dims) throw new Error(`${req.model}: vector of dimension ${v && v.length}, expected ${req.dims}`);
    if (!groups.has(req.model)) groups.set(req.model, []);
    groups.get(req.model).push({ chunk_id: req.chunk_ids[j], embedding: v });
  });
});
const out = [];
for (const [model, rows] of groups) {
  for (let i = 0; i < rows.length; i += 200) out.push({ json: { model, rows: JSON.stringify(rows.slice(i, i + 200)) } });
}
return out;

// wf.kb.ingest_source > "Result" (after embeddings) and "Skipped" (nothing to do)
// Output: the outcome returned to wf.kb.ingest.
const x = $('Robots decision').first().json;
const mode = 'done';
const base = { job_id: x.job_id, source_id: x.source.id, source_key: x.source.source_key, ms: Date.now() - x.t0 };
if (mode === 'robots') {
  return [{ json: { ...base, status: 'skipped', step: 'robots', action: null, detail: { robots: x.robots } } }];
}
const doc = $('Store document').first().json.doc;
if (mode === 'unchanged') {
  return [{ json: { ...base, status: 'skipped', step: 'unchanged', action: doc.action, detail: { doc, robots: x.robots } } }];
}
const ch = $('Chunk').first().json;
const counts = {};
for (const it of $input.all()) {
  const n = Number(it.json.n || 0);
  counts[it.json.model] = (counts[it.json.model] || 0) + n;
}
const cleaned = $('Cleaned').first().json;
return [{ json: { ...base, status: 'ok', step: 'done', action: doc.action,
  chunks: ch.stats, embeddings: counts,
  detail: { doc, robots: x.robots, document_tokens: ch.document_tokens, offset_units: ch.offset_units,
            chunk_ms: ch.chunk_ms, extractor: cleaned.extractor, doc_metadata: cleaned.doc_metadata } } }];
